class Driver {
  + id : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licencePlate : string
  + isInRepairShop : boolean
}

class BusRoute {
  + routeNumber : int
}

class ShiftType {
  MORNING
  AFTERNOON
  NIGHT
}

class Assignment {
  + date : date
}

class Shift {
  + shiftType : ShiftType
}

CityStaff "1" -- "*" BusRoute : manages
CityStaff "1" -- "*" Driver : manages
CityStaff "1" -- "*" Bus : manages
CityStaff "1" -- "*" Assignment : creates
CityStaff "1" -- "*" Shift : creates

BusRoute "1" -- "*" Assignment : has
Bus "1" -- "*" Assignment : is assigned to
Driver "1" -- "*" Assignment : is assigned to
Assignment "1" -- "1" Shift : has

@enduml

